import numpy as np
from typing import List, Optional
from scipy import spatial

class SearchArray:
    def __init__(self, field: str, data: pd.Series):
        self.field = field
        self.data = data

    def score(self, query_terms: List[str], similarity: str = "BM25") -> np.ndarray:
        if similarity == "BM25":
            return self._bm25_score(query_terms)
        elif similarity == "TF-IDF":
            return self._tf_idf_score(query_terms)
        else:
            raise ValueError("Unsupported similarity measure")

    def _bm25_score(self, query_terms: List[str]) -> np.ndarray:
        # BM25 scoring function implementation
        # This is a simplified version and may not cover all edge cases
        scores = []
        for term in query_terms:
            term_freq = self.data[self.field].str.count(term).sum()
            doc_freq = len(self.data[self.field].unique())
            avg_doc_len = len(self.data[self.field])
            k1 = 1.2
            b = 0.75
            score = (k1 + 1) * term_freq / (k1 * (1 - b + b * (len(self.data[self.field]) / avg_doc_len)) + term_freq)
            scores.append(score)
        return np.array(scores)

    def _tf_idf_score(self, query_terms: List[str]) -> np.ndarray:
        # TF-IDF scoring function implementation
        # This is a simplified version and may not cover all edge cases
        scores = []
        for term in query_terms:
            term_freq = self.data[self.field].str.count(term).sum()
            doc_freq = len(self.data[self.field].unique())
            idf = np.log(len(self.data) / doc_freq)
            tf = term_freq / len(self.data[self.field])
            score = tf * idf
            scores.append(score)
        return np.array(scores)


